let qi=0,sc=0,wr=[];
function qr(){const q=$('#qz');if(qi>=Q.length){const b=ld();b.best=Math.max(b.best||0,sc);sv(b);q.innerHTML=`<h3>Resultado: ${sc}/${Q.length} (${Math.round(sc/Q.length*100)}%)</h3><p>${sc>=16?'🏆 Excelente! Pronto para o próximo nível.':sc>=10?'👍 Bom caminho, revise os erros.':'📚 Continue estudando!'}</p>${wr.length?'<h4>Para revisar</h4>'+wr.map(i=>`<div class="exp"><b>${Q[i][0]}</b><br>Resposta: ${Q[i][1][Q[i][2]]}. ${Q[i][3]}</div>`).join(''):''}<button onclick="qi=sc=0;wr=[];qr()" style="margin-top:12px">Refazer</button>`;return}
const c=Q[qi];q.innerHTML=`<div class="bar"><div style="width:${qi/Q.length*100}%"></div></div><p>Questão ${qi+1} de ${Q.length}</p><h3>${c[0]}</h3>${c[1].map((o,i)=>`<button class="opt" onclick="ans(${i})">${'ABCD'[i]}) ${o}</button>`).join('')}<div id="fb"></div>`}
function ans(i){const c=Q[qi],bs=document.querySelectorAll('.opt');if($('#fb').innerHTML)return;bs.forEach((b,j)=>{if(j==c[2])b.classList.add('ok');else if(j==i)b.classList.add('no')});if(i==c[2])sc++;else wr.push(qi);$('#fb').innerHTML=`<div class="exp">${i==c[2]?'✅ <b>Você acertou!</b> Porque: ':'❌ <b>Você errou.</b> A correta é '+'ABCD'[c[2]]+'. Porque: '}${c[3]}</div><button onclick="qi++;qr()" style="margin-top:10px">${qi==Q.length-1?'Ver resultado':'Próxima ➜'}</button>`}
qr();
