$('#dz').innerHTML=[['❤️ Coração',[['Infarto agudo do miocárdio','Dor torácica opressiva, sudorese, dor no braço esquerdo. Emergência: ligue 192.'],['Insuficiência cardíaca','O coração não bombeia o suficiente: cansaço, falta de ar e inchaço nas pernas.'],['Hipertensão arterial','Pressão ≥ 140/90 mmHg. Silenciosa; causa AVC, infarto e lesão renal. Controle com sal baixo e exercício.']]],['🫁 Pulmão',[['Asma','Inflamação crônica dos brônquios: chiado e falta de ar em crises; tratada com broncodilatadores e corticoides inalados.'],['DPOC','Obstrução crônica do ar, causada principalmente pelo cigarro (enfisema e bronquite).'],['Pneumonia','Infecção dos alvéolos: febre, tosse com secreção, dor ao respirar.']]],['🫘 Rim',[['Doença renal crônica','Perda progressiva da filtração; diabetes e hipertensão são as principais causas.'],['Cálculo renal','Pedras de cálcio ou ácido úrico; causam cólica intensa. Beba bastante água.'],['Pielonefrite','Infecção urinária que sobe ao rim: febre, dor lombar, calafrios.']]],['🧠 Cérebro',[['AVC','Obstrução (isquêmico) ou sangramento (hemorrágico): rosto torto, fraqueza de um lado, fala arrastada. Corra: cada minuto conta.'],['Epilepsia','Descargas elétricas anormais causando crises convulsivas; tratada com anticonvulsivantes.'],['Doença de Alzheimer','Demência progressiva com perda de memória por degeneração neuronal.']]]].map(o=>`<h3>${o[0]}</h3>`+o[1].map(d=>`<details><summary>${d[0]}</summary><p>${d[1]}</p></details>`).join('')).join('');
