$('#nf').innerHTML=`<label>Sexo</label><select id="fs"><option value="m">Masculino</option><option value="f">Feminino</option></select><label>Idade (anos)</label><input id="fi" type="number" value="20"><label>Peso (kg)</label><input id="fp" type="number" value="70"><label>Altura (cm)</label><input id="fa" type="number" value="175"><label>Nível de atividade</label><select id="fx"><option value="1.2">Sedentário</option><option value="1.375" selected>Leve (1–3x/semana)</option><option value="1.55">Moderado (3–5x)</option><option value="1.725">Intenso (6–7x)</option></select><label>Objetivo</label><select id="fo"><option value="-0.2">Emagrecer</option><option value="0" selected>Manter</option><option value="0.1">Ganhar massa</option></select>`;
function calc(){const v=i=>+$('#'+i).value,s=$('#fs').value,p=v('fp'),a=v('fa'),h=a/100,tmb=10*p+6.25*a-5*v('fi')+(s=='m'?5:-161),get=tmb*v('fx'),k=Math.round(get*(1+v('fo'))),imc=p/(h*h),pr=Math.round(p*(v('fo')>0?2:1.8)),g=Math.round(k*.25/9),c=Math.round((k-pr*4-g*9)/4),cl=imc<18.5?'abaixo do peso':imc<25?'peso normal':imc<30?'sobrepeso':'obesidade';
const m=[['☕ Café da manhã',.25,'pão integral, ovos, fruta, café/leite'],['🍛 Almoço',.35,'arroz, feijão, carne/frango/peixe, salada e legumes'],['🍌 Lanche',.15,'iogurte, frutas, castanhas'],['🍲 Jantar',.25,'proteína magra, legumes, carboidrato em menor porção']];
$('#nr').innerHTML=`<h3>Seu plano</h3><p>IMC: <b>${imc.toFixed(1)}</b> (${cl})<br>Metabolismo basal: <b>${Math.round(tmb)} kcal</b><br>Gasto diário total: <b>${Math.round(get)} kcal</b><br>Meta diária: <b>${k} kcal</b></p><p>Proteínas <b>${pr} g</b> · Carboidratos <b>${c} g</b> · Gorduras <b>${g} g</b><br>Água: <b>${(p*.035).toFixed(1)} L</b>/dia</p>${m.map(x=>`<div class="exp"><b>${x[0]}</b> ≈ ${Math.round(k*x[1])} kcal<br>${x[2]}</div>`).join('')}<p style="color:var(--mut)">Cálculo pela equação de Mifflin-St Jeor. É uma estimativa: procure um nutricionista para um plano individual.</p>`;const b=ld();b.plan={imc:imc.toFixed(1),k};sv(b)}
