const T={'Iniciante':['Seg: caminhada 30 min + alongamento','Ter: agachamento, flexão (joelhos), remada, prancha – 3×10','Qui: bicicleta/caminhada 30 min','Sex: repita terça com mais carga','Descanso ativo no fim de semana'],'Hipertrofia':['Seg: peito e tríceps','Ter: costas e bíceps','Qua: descanso','Qui: pernas e glúteos','Sex: ombros e abdômen','Séries 3–4×8–12; sobrecarga progressiva; dormir 7–9 h e comer proteína'],'Emagrecimento':['3× semana musculação de corpo inteiro','2× semana cardio moderado 30–40 min','1× HIIT curto (20 min)','Meta: 8–10 mil passos por dia','Déficit moderado de calorias; evite dietas extremas'],'Saúde e postura':['Diário: 10 min de mobilidade (gato-vaca, alongar quadril e peitoral)','3× semana: 150 min por semana de aeróbico moderado (recomendação da OMS)','2× semana: fortalecimento de core e glúteos','A cada hora sentado, levante 2 min']};
$('#tt').innerHTML=Object.keys(T).map((k,i)=>`<button class="alt ${i?'':'on'}" onclick="tr('${k}',this)">${k}</button>`).join('');
function tr(k,b){document.querySelectorAll('#tt button').forEach(x=>x.classList.toggle('on',x==b));$('#tb').innerHTML=`<h3>${k}</h3><ul>${T[k].map(x=>`<li>${x}</li>`).join('')}</ul><p style="color:var(--mut)">Aqueça 5–10 min e consulte um médico antes de iniciar se tiver doenças ou dores.</p>`}tr('Iniciante',$('#tt button'));
