function saveC(){const b=ld();b.nome=$('#cn').value;b.meta=$('#cm').value;sv(b);acc()}
function acc(){const b=ld();$('#cn').value=b.nome||'';if(b.meta)$('#cm').value=b.meta;$('#cs').innerHTML=`<h3>Olá, ${b.nome||'estudante'}! 👋</h3><p>Melhor nota no quiz: <b>${b.best!=null?b.best+'/20':'—'}</b><br>Último plano: <b>${b.plan?b.plan.k+' kcal · IMC '+b.plan.imc:'—'}</b></p><p style="color:var(--mut)">Seus dados ficam salvos só neste navegador.</p>`}
